import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  img: { fill: '#e8f5e9', stroke: '#4caf50' },
  patch: { fill: '#e3f2fd', stroke: '#1976d2' },
  text: { fill: '#fff3e0', stroke: '#e65100' },
  tok: { fill: '#fce4ec', stroke: '#c62828' },
  enc: { fill: '#ede7f6', stroke: '#4527a0' },
  proj: { fill: '#e0f2f1', stroke: '#00897b' },
  norm: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  sim: { fill: '#fff9c4', stroke: '#f57f17' },
  loss: { fill: '#ffebee', stroke: '#b71c1c' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  textCol: 'var(--text)' as string,
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 62;
const BOX_W = 370;
const MAT_H = 68;
const SEQ_W = 170;
const BOX_TO_ROW = 70;
const ROW_GAP = 52;
const STEP_GAP = 60;
const IMG_CX = 250;
const TXT_CX = 710;

function lbl(g: Gsel, x: number, y: number, t: string, opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}): void {
  drawLabel(g as Sel, x, y, t, opts);
}
function arrowV(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void { drawArrow(g as Sel, x, y1, x, y2, { color }); }
function startGroup(g: Gsel, cls: string, step: number): Gsel { return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step)); }

function branchHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string, fill: string, stroke: string, width = BOX_W): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H).attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 22).attr('cy', y + BOX_H / 2).attr('r', 13).attr('fill', stroke);
  lbl(g, cx - w / 2 + 22, y + BOX_H / 2 + 1, String(sn), { size: 11, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 44, y + BOX_H / 2 - 5, title, { size: 12, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 44, y + BOX_H / 2 + 10, formula, { size: 8, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6 + 24, 160);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 13).attr('width', w).attr('height', 26).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8, color, font: 'monospace' });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const bw = Math.max(80, text.length * 7 + 18);
  g.append('rect').attr('x', cx - bw / 2).attr('y', cy - 15).attr('width', bw).attr('height', 30).attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 9, weight: '600', color: stroke });
}

function drawSeqMat(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = SEQ_W, h = MAT_H): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 7, rows: 4, dimTop: 'S', dimRight: 'D' });
}

function drawWeightMat(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke, w = 120, h = 68): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 4 });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 16).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 12, weight: '700', color });
}

function drawParamSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160; const h = 32;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => { lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 9.5, color: COLORS.muted, font: 'monospace' }); });
  return y + h;
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string, sg: string, c: string, fl: string, cl?: string[]): StepInfo {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex, code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawImageGrid(g: Gsel, cx: number, cy: number, gridN: number, color: string, size = 160): void {
  const gg = g.append('g').attr('transform', `translate(${cx - size / 2}, ${cy - size / 2})`);
  gg.append('rect').attr('width', size).attr('height', size).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const cw = size / gridN; const ch = size / gridN;
  let seed = 42;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let r = 0; r < gridN; r++) for (let c = 0; c < gridN; c++) {
    gg.append('rect').attr('x', c * cw + 0.5).attr('y', r * ch + 0.5).attr('width', cw - 1).attr('height', ch - 1).attr('rx', 1).attr('fill', color).attr('opacity', 0.15 + lcg() * 0.55);
  }
  if (gridN <= 14) for (let i = 1; i < gridN; i++) {
    gg.append('line').attr('x1', i * cw).attr('y1', 0).attr('x2', i * cw).attr('y2', size).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
    gg.append('line').attr('x1', 0).attr('y1', i * ch).attr('x2', size).attr('y2', i * ch).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
  }
}

function drawTokenStrip(g: Gsel, cx: number, cy: number, nShow: number, color: string, w = 280, h = 48): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w / 2}, ${cy - h / 2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const cw = w / (nShow + 1);
  for (let i = 0; i < nShow; i++) {
    const op = 0.15 + (i / nShow) * 0.5;
    gg.append('rect').attr('x', i * cw + 2).attr('y', 4).attr('width', cw - 4).attr('height', h - 8).attr('rx', 2).attr('fill', color).attr('opacity', op);
  }
}

function drawPosEncoding(g: Gsel, cx: number, cy: number, n: number, color: string, w = 220, h = 56): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w / 2}, ${cy - h / 2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 0.8);
  const nCols = Math.min(n, 14); const nRows = 4;
  const cw = w / nCols; const ch = h / nRows;
  for (let r = 0; r < nRows; r++) for (let c = 0; c < nCols; c++) {
    const v = Math.sin(c * 0.5 + r * 1.3) * 0.4 + 0.5;
    gg.append('rect').attr('x', c * cw).attr('y', r * ch).attr('width', cw - 0.5).attr('height', ch - 0.5).attr('rx', 1).attr('fill', color).attr('opacity', Math.max(0.05, v * 0.6));
  }
}

function renderClipPipeline(g: Gsel, startY: number, dModel: number, nPatches: number, seqLen: number): { steps: StepInfo[]; y: number } {
  const steps: StepInfo[] = [];
  let y = startY;
  const patchSize = 16;
  const gridN = Math.round(Math.sqrt(nPatches));
  const dProj = dModel;

  // ═══════════════════════════════════════════════════════════════════════
  // IMAGE BRANCH (left)
  // ═══════════════════════════════════════════════════════════════════════
  let imgStepId = 1;
  let iy = y;

  // ── I1: Input Image ──
  {
    const gs = startGroup(g, 'step-img', imgStepId);
    const h = branchHeader(gs, IMG_CX, iy, imgStepId, 'Input Image', `[3, ${patchSize * gridN}, ${patchSize * gridN}]`, COLORS.img.fill, COLORS.img.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.img.stroke);
    const gridCY = h + BOX_TO_ROW + 80;
    drawImageGrid(gs, IMG_CX, gridCY, Math.min(gridN, 14), COLORS.img.stroke, 160);
    lbl(gs, IMG_CX, gridCY + 80 + 16, `${patchSize * gridN}×${patchSize * gridN} RGB`, { size: 8, color: COLORS.muted });
    steps.push(makeStep(imgStepId, 'Image', 'Input Image', `[3, ${patchSize * gridN}, ${patchSize * gridN}]`, `Input RGB image of size ${patchSize * gridN}×${patchSize * gridN}.`, 'step-img', COLORS.img.stroke, COLORS.img.fill));
    imgStepId++; iy = gridCY + 80 + STEP_GAP;
  }

  // ── I2: Patchify ──
  {
    const gs = startGroup(g, 'step-patch', imgStepId);
    const h = branchHeader(gs, IMG_CX, iy, imgStepId, 'Patchify', `→ [${nPatches}, ${patchSize * patchSize * 3}]`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.patch.stroke);
    const rowY = h + BOX_TO_ROW + 24;
    drawTokenStrip(gs, IMG_CX, rowY, Math.min(nPatches, 10), COLORS.patch.stroke, 260, 44);
    lbl(gs, IMG_CX, rowY - 32, `${nPatches} patches`, { size: 8.5, color: COLORS.muted });
    lbl(gs, IMG_CX, rowY + 32, `each: ${patchSize * patchSize * 3}d`, { size: 8, color: COLORS.muted });
    const outY = rowY + 22 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX, rowY + 22 + 16, outY - MAT_H / 2, COLORS.patch.stroke);
    drawSeqMat(gs, IMG_CX, outY, 'patches', `[${nPatches}, ${patchSize * patchSize * 3}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, IMG_CX, outY + MAT_H / 2 + 20, `reshape → [${nPatches}, ${patchSize * patchSize * 3}]`, COLORS.patch.stroke);
    steps.push(makeStep(imgStepId, 'Patchify', 'Patchify', `reshape → [${nPatches}, ${patchSize * patchSize * 3}]`, 'Split image into patches and flatten.', 'step-patch', COLORS.patch.stroke, COLORS.patch.fill));
    imgStepId++; iy = outY + MAT_H / 2 + 20 + STEP_GAP;
  }

  // ── I3: Linear Projection ──
  {
    const gs = startGroup(g, 'step-proj', imgStepId);
    const h = branchHeader(gs, IMG_CX, iy, imgStepId, 'Linear Projection', `patches · W_p + b`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.patch.stroke);
    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, IMG_CX - 40, rowY, 'patches', `[${nPatches}, ${patchSize * patchSize * 3}]`, COLORS.patch.fill, COLORS.patch.stroke, 140, MAT_H);
    opCircle(gs, IMG_CX + 70, rowY, '×', COLORS.patch.stroke);
    drawArrow(gs as Sel, IMG_CX - 40 + 70 + 4, rowY, IMG_CX + 70 - 18, rowY, { color: COLORS.patch.stroke });
    const wpX = IMG_CX + 160;
    drawWeightMat(gs, wpX, rowY, 'W_p', `[${patchSize * patchSize * 3}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 58);
    drawArrow(gs as Sel, IMG_CX + 70 + 18, rowY, wpX - 50 - 4, rowY, { color: COLORS.patch.stroke });
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX + 40, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.patch.stroke);
    drawSeqMat(gs, IMG_CX, outY, 'img_emb', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, IMG_CX, outY + MAT_H / 2 + 20, `patches · W_p + b → [${nPatches}, ${dModel}]`, COLORS.patch.stroke);
    steps.push(makeStep(imgStepId, 'Project', 'Linear Projection', `patches · W_p + b`, 'Project patches to d_model.', 'step-proj', COLORS.patch.stroke, COLORS.patch.fill));
    imgStepId++; iy = outY + MAT_H / 2 + 20 + STEP_GAP;
  }

  // ── I4: ViT Transformer Encoder ──
  {
    const gs = startGroup(g, 'step-vit', imgStepId);
    const h = branchHeader(gs, IMG_CX, iy, imgStepId, 'ViT Encoder (×L)', `h = x + Attn(LN(x))`, COLORS.enc.fill, COLORS.enc.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.enc.stroke);
    const inY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, IMG_CX, inY, 'img_emb', `[${nPatches + 1}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke);
    lbl(gs, IMG_CX + SEQ_W / 2 + 14, inY, '+CLS', { size: 7, color: COLORS.muted, anchor: 'start' });
    const encBoxY = inY + MAT_H / 2 + ROW_GAP;
    const encBoxH = 130;
    gs.append('rect').attr('x', IMG_CX - BOX_W / 2 + 20).attr('y', encBoxY).attr('width', BOX_W - 40).attr('height', encBoxH).attr('rx', 8).attr('fill', COLORS.enc.fill).attr('stroke', COLORS.enc.stroke).attr('stroke-width', 1).attr('stroke-dasharray', '4,2').attr('opacity', 0.5);
    lbl(gs, IMG_CX - BOX_W / 2 + 32, encBoxY + 14, 'Transformer Layers', { size: 9, weight: '600', color: COLORS.enc.stroke, anchor: 'start' });
    arrowV(gs, IMG_CX, inY + MAT_H / 2, encBoxY, COLORS.enc.stroke);
    const lnY = encBoxY + 44;
    drawBadge(gs, IMG_CX, lnY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    const attnY = lnY + 46;
    drawBadge(gs, IMG_CX - 60, attnY, 'MHA', COLORS.enc.fill, COLORS.enc.stroke);
    drawBadge(gs, IMG_CX + 60, attnY, 'FFN', COLORS.enc.fill, COLORS.enc.stroke);
    lbl(gs, IMG_CX, attnY + 1, '+residual', { size: 7, color: COLORS.muted });
    const outY = encBoxY + encBoxH + ROW_GAP + 15;
    arrowV(gs, IMG_CX, encBoxY + encBoxH, outY - 15, COLORS.enc.stroke);
    drawBadge(gs, IMG_CX, outY, 'CLS extract', COLORS.img.fill, COLORS.img.stroke);
    const boxBottom = outY + 15;
    const featY = boxBottom + ROW_GAP + 20;
    arrowV(gs, IMG_CX, outY + 15, featY - 20, COLORS.img.stroke);
    const featW = 200; const featH = 38;
    gs.append('rect').attr('x', IMG_CX - featW / 2).attr('y', featY - featH / 2).attr('width', featW).attr('height', featH).attr('rx', 6).attr('fill', COLORS.img.fill).attr('stroke', COLORS.img.stroke).attr('stroke-width', 1.5);
    lbl(gs, IMG_CX, featY + 1, `img_features [${dModel}]`, { size: 8.5, weight: '600', color: COLORS.img.stroke });
    steps.push(makeStep(imgStepId, 'ViT', 'ViT Encoder', `h = x + Attn(LN(x))`, 'Vision transformer encoder extracts CLS features.', 'step-vit', COLORS.enc.stroke, COLORS.enc.fill));
    imgStepId++; iy = featY + featH / 2 + STEP_GAP;
  }

  // ── I5: Image Projection ──
  {
    const gs = startGroup(g, 'step-iproj', imgStepId);
    const h = branchHeader(gs, IMG_CX, iy, imgStepId, 'Image Projection', `f_i · W_i`, COLORS.proj.fill, COLORS.proj.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.proj.stroke);
    const rowY = h + BOX_TO_ROW + 20;
    const vecW = 180; const vecH = 34;
    gs.append('rect').attr('x', IMG_CX - 60 - vecW / 2).attr('y', rowY - vecH / 2).attr('width', vecW).attr('height', vecH).attr('rx', 5).attr('fill', COLORS.img.fill).attr('stroke', COLORS.img.stroke).attr('stroke-width', 1);
    lbl(gs, IMG_CX - 60, rowY + 1, `img [${dModel}]`, { size: 8.5, weight: '600', color: COLORS.img.stroke });
    opCircle(gs, IMG_CX + 40, rowY, '×', COLORS.proj.stroke);
    drawArrow(gs as Sel, IMG_CX - 60 + vecW / 2 + 4, rowY, IMG_CX + 40 - 18, rowY, { color: COLORS.proj.stroke });
    drawWeightMat(gs, IMG_CX + 140, rowY, 'W_i', `[${dModel}, ${dProj}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 56);
    drawArrow(gs as Sel, IMG_CX + 40 + 18, rowY, IMG_CX + 140 - 50 - 4, rowY, { color: COLORS.proj.stroke });
    const outY = rowY + vecH / 2 + ROW_GAP + 18;
    arrowV(gs, IMG_CX + 40, rowY + vecH / 2, outY - 18, COLORS.proj.stroke);
    const outW = 180; const outH = 34;
    gs.append('rect').attr('x', IMG_CX - outW / 2).attr('y', outY - outH / 2).attr('width', outW).attr('height', outH).attr('rx', 6).attr('fill', COLORS.proj.fill).attr('stroke', COLORS.proj.stroke).attr('stroke-width', 1.5);
    lbl(gs, IMG_CX, outY + 1, `proj_img [${dProj}]`, { size: 8.5, weight: '600', color: COLORS.proj.stroke });
    drawShapeEq(gs, IMG_CX, outY + outH / 2 + 18, `img_features · W_i → [${dProj}]`, COLORS.proj.stroke);
    steps.push(makeStep(imgStepId, 'Proj_i', 'Image Projection', `f_i · W_i`, 'Project image features to shared embedding space.', 'step-iproj', COLORS.proj.stroke, COLORS.proj.fill));
    iy = outY + outH / 2 + 18 + STEP_GAP;
  }

  const imgBottom = iy;

  // ═══════════════════════════════════════════════════════════════════════
  // TEXT BRANCH (right)
  // ═══════════════════════════════════════════════════════════════════════
  let txtStepId = 5;
  let ty = y;

  // ── T1: Input Text ──
  {
    const gs = startGroup(g, 'step-text', txtStepId);
    const h = branchHeader(gs, TXT_CX, ty, txtStepId, 'Input Text', `tokens: [${seqLen}]`, COLORS.text.fill, COLORS.text.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.text.stroke);
    const stripY = h + BOX_TO_ROW + 24;
    drawTokenStrip(gs, TXT_CX, stripY, Math.min(seqLen, 12), COLORS.text.stroke, 280, 44);
    lbl(gs, TXT_CX, stripY - 32, `"a photo of a cat"`, { size: 8.5, color: COLORS.muted });
    lbl(gs, TXT_CX, stripY + 32, `${seqLen} tokens (BPE)`, { size: 8, color: COLORS.muted });
    const outY = stripY + 22 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX, stripY + 22 + 16, outY - MAT_H / 2, COLORS.text.stroke);
    drawSeqMat(gs, TXT_CX, outY, 'token_ids', `[${seqLen}]`, COLORS.text.fill, COLORS.text.stroke, SEQ_W, MAT_H - 10);
    steps.push(makeStep(txtStepId, 'Text', 'Input Text', `[${seqLen}]`, `Tokenized text input (${seqLen} BPE tokens).`, 'step-text', COLORS.text.stroke, COLORS.text.fill));
    txtStepId++; ty = outY + MAT_H / 2 + STEP_GAP;
  }

  // ── T2: Token + Position Embedding ──
  {
    const gs = startGroup(g, 'step-emb', txtStepId);
    const h = branchHeader(gs, TXT_CX, ty, txtStepId, 'Token + Pos Embedding', `E(tok) + PE`, COLORS.tok.fill, COLORS.tok.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.tok.stroke);
    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, TXT_CX - 50, rowY, 'E(tok)', `[${seqLen}, ${dModel}]`, COLORS.tok.fill, COLORS.tok.stroke, 140, MAT_H);
    opCircle(gs, TXT_CX + 50, rowY, '+', COLORS.tok.stroke);
    drawArrow(gs as Sel, TXT_CX - 50 + 70 + 4, rowY, TXT_CX + 50 - 18, rowY, { color: COLORS.tok.stroke });
    const peW = 120; const peH = 50;
    drawPosEncoding(gs, TXT_CX + 140, rowY, seqLen, COLORS.tok.stroke, peW, peH);
    lbl(gs, TXT_CX + 140, rowY - peH / 2 - 10, 'learned PE', { size: 7.5, color: COLORS.muted });
    drawArrow(gs as Sel, TXT_CX + 140 - peW / 2 - 4, rowY, TXT_CX + 50 + 18, rowY, { color: COLORS.tok.stroke });
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX + 50, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.tok.stroke);
    drawSeqMat(gs, TXT_CX, outY, 'tokens', `[${seqLen}, ${dModel}]`, COLORS.tok.fill, COLORS.tok.stroke);
    drawShapeEq(gs, TXT_CX, outY + MAT_H / 2 + 20, `E(tok) + PE → [${seqLen}, ${dModel}]`, COLORS.tok.stroke);
    steps.push(makeStep(txtStepId, 'Embed', 'Token + Pos Embedding', `E(tok) + PE`, 'Token embedding + learned positional encoding.', 'step-emb', COLORS.tok.stroke, COLORS.tok.fill));
    txtStepId++; ty = outY + MAT_H / 2 + 20 + STEP_GAP;
  }

  // ── T3: Text Transformer Encoder ──
  {
    const gs = startGroup(g, 'step-tenc', txtStepId);
    const h = branchHeader(gs, TXT_CX, ty, txtStepId, 'Text Encoder (×L)', `h = x + Attn(LN(x))`, COLORS.enc.fill, COLORS.enc.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.enc.stroke);
    const inY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, TXT_CX, inY, 'tokens', `[${seqLen}, ${dModel}]`, COLORS.tok.fill, COLORS.tok.stroke);
    const encBoxY = inY + MAT_H / 2 + ROW_GAP;
    const encBoxH = 130;
    gs.append('rect').attr('x', TXT_CX - BOX_W / 2 + 20).attr('y', encBoxY).attr('width', BOX_W - 40).attr('height', encBoxH).attr('rx', 8).attr('fill', COLORS.enc.fill).attr('stroke', COLORS.enc.stroke).attr('stroke-width', 1).attr('stroke-dasharray', '4,2').attr('opacity', 0.5);
    lbl(gs, TXT_CX - BOX_W / 2 + 32, encBoxY + 14, 'Transformer Layers', { size: 9, weight: '600', color: COLORS.enc.stroke, anchor: 'start' });
    arrowV(gs, TXT_CX, inY + MAT_H / 2, encBoxY, COLORS.enc.stroke);
    const lnY = encBoxY + 44;
    drawBadge(gs, TXT_CX, lnY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    const attnY = lnY + 46;
    drawBadge(gs, TXT_CX - 60, attnY, 'MHA', COLORS.enc.fill, COLORS.enc.stroke);
    drawBadge(gs, TXT_CX + 60, attnY, 'FFN', COLORS.enc.fill, COLORS.enc.stroke);
    lbl(gs, TXT_CX, attnY + 1, '+residual', { size: 7, color: COLORS.muted });
    const outY = encBoxY + encBoxH + ROW_GAP + 15;
    arrowV(gs, TXT_CX, encBoxY + encBoxH, outY - 15, COLORS.enc.stroke);
    drawBadge(gs, TXT_CX, outY, 'EOS extract', COLORS.text.fill, COLORS.text.stroke);
    const boxBottom = outY + 15;
    const featY = boxBottom + ROW_GAP + 20;
    arrowV(gs, TXT_CX, outY + 15, featY - 20, COLORS.text.stroke);
    const featW = 200; const featH = 38;
    gs.append('rect').attr('x', TXT_CX - featW / 2).attr('y', featY - featH / 2).attr('width', featW).attr('height', featH).attr('rx', 6).attr('fill', COLORS.text.fill).attr('stroke', COLORS.text.stroke).attr('stroke-width', 1.5);
    lbl(gs, TXT_CX, featY + 1, `txt_features [${dModel}]`, { size: 8.5, weight: '600', color: COLORS.text.stroke });
    steps.push(makeStep(txtStepId, 'TextEnc', 'Text Encoder', `h = x + Attn(LN(x))`, 'Transformer encoder for text. EOS token aggregates.', 'step-tenc', COLORS.enc.stroke, COLORS.enc.fill));
    txtStepId++; ty = featY + featH / 2 + STEP_GAP;
  }

  // ── T4: Text Projection ──
  {
    const gs = startGroup(g, 'step-tproj', txtStepId);
    const h = branchHeader(gs, TXT_CX, ty, txtStepId, 'Text Projection', `f_t · W_t`, COLORS.proj.fill, COLORS.proj.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.proj.stroke);
    const rowY = h + BOX_TO_ROW + 20;
    const vecW = 180; const vecH = 34;
    gs.append('rect').attr('x', TXT_CX - 60 - vecW / 2).attr('y', rowY - vecH / 2).attr('width', vecW).attr('height', vecH).attr('rx', 5).attr('fill', COLORS.text.fill).attr('stroke', COLORS.text.stroke).attr('stroke-width', 1);
    lbl(gs, TXT_CX - 60, rowY + 1, `txt [${dModel}]`, { size: 8.5, weight: '600', color: COLORS.text.stroke });
    opCircle(gs, TXT_CX + 40, rowY, '×', COLORS.proj.stroke);
    drawArrow(gs as Sel, TXT_CX - 60 + vecW / 2 + 4, rowY, TXT_CX + 40 - 18, rowY, { color: COLORS.proj.stroke });
    drawWeightMat(gs, TXT_CX + 140, rowY, 'W_t', `[${dModel}, ${dProj}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 56);
    drawArrow(gs as Sel, TXT_CX + 40 + 18, rowY, TXT_CX + 140 - 50 - 4, rowY, { color: COLORS.proj.stroke });
    const outY = rowY + vecH / 2 + ROW_GAP + 18;
    arrowV(gs, TXT_CX + 40, rowY + vecH / 2, outY - 18, COLORS.proj.stroke);
    const outW = 180; const outH = 34;
    gs.append('rect').attr('x', TXT_CX - outW / 2).attr('y', outY - outH / 2).attr('width', outW).attr('height', outH).attr('rx', 6).attr('fill', COLORS.proj.fill).attr('stroke', COLORS.proj.stroke).attr('stroke-width', 1.5);
    lbl(gs, TXT_CX, outY + 1, `proj_txt [${dProj}]`, { size: 8.5, weight: '600', color: COLORS.proj.stroke });
    drawShapeEq(gs, TXT_CX, outY + outH / 2 + 18, `txt_features · W_t → [${dProj}]`, COLORS.proj.stroke);
    steps.push(makeStep(txtStepId, 'Proj_t', 'Text Projection', `f_t · W_t`, 'Project text features to shared embedding space.', 'step-tproj', COLORS.proj.stroke, COLORS.proj.fill));
    ty = outY + outH / 2 + 18 + STEP_GAP;
  }

  const txtBottom = ty;

  // ═══════════════════════════════════════════════════════════════════════
  // CONTRASTIVE SECTION (center)
  // ═══════════════════════════════════════════════════════════════════════
  let cStepId = 9;
  y = Math.max(imgBottom, txtBottom);

  // ── C1: L2 Normalize ──
  {
    const gs = startGroup(g, 'step-norm', cStepId);
    const h = branchHeader(gs, CX, y, cStepId, 'L2 Normalize', `f̂ = f / ‖f‖₂`, COLORS.norm.fill, COLORS.norm.stroke, 600);
    arrowV(gs, IMG_CX, imgBottom - STEP_GAP + 40, h, COLORS.norm.stroke);
    arrowV(gs, TXT_CX, txtBottom - STEP_GAP + 40, h, COLORS.norm.stroke);
    const rowY = h + BOX_TO_ROW + 18;
    const normW = 180; const normH = 34;
    gs.append('rect').attr('x', IMG_CX - normW / 2).attr('y', rowY - normH / 2).attr('width', normW).attr('height', normH).attr('rx', 6).attr('fill', COLORS.norm.fill).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1.5);
    lbl(gs, IMG_CX, rowY + 1, `f̂_img [${dProj}]`, { size: 8.5, weight: '600', color: COLORS.norm.stroke });
    gs.append('rect').attr('x', TXT_CX - normW / 2).attr('y', rowY - normH / 2).attr('width', normW).attr('height', normH).attr('rx', 6).attr('fill', COLORS.norm.fill).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1.5);
    lbl(gs, TXT_CX, rowY + 1, `f̂_txt [${dProj}]`, { size: 8.5, weight: '600', color: COLORS.norm.stroke });
    drawShapeEq(gs, CX, rowY + normH / 2 + 18, `f̂ = f / ‖f‖₂  (unit sphere)`, COLORS.norm.stroke);
    steps.push(makeStep(cStepId, 'Norm', 'L2 Normalize', `f̂ = f / ‖f‖₂`, 'Normalize to unit norm for cosine similarity.', 'step-norm', COLORS.norm.stroke, COLORS.norm.fill));
    cStepId++; y = rowY + normH / 2 + 18 + STEP_GAP;
  }

  const normRowBottom = y;

  // ── C2: Cosine Similarity ──
  {
    const gs = startGroup(g, 'step-sim', cStepId);
    const h = branchHeader(gs, CX, y, cStepId, 'Cosine Similarity', `sim = f̂_img · f̂_txt`, COLORS.sim.fill, COLORS.sim.stroke, 600);
    arrowV(gs, IMG_CX + 40, normRowBottom - STEP_GAP + 36, h + BOX_H, COLORS.norm.stroke);
    arrowV(gs, TXT_CX - 40, normRowBottom - STEP_GAP + 36, h + BOX_H, COLORS.norm.stroke);
    const simY = h + BOX_TO_ROW + 18;
    const simW = 280; const simH = 38;
    gs.append('rect').attr('x', CX - simW / 2).attr('y', simY - simH / 2).attr('width', simW).attr('height', simH).attr('rx', 8).attr('fill', COLORS.sim.fill).attr('stroke', COLORS.sim.stroke).attr('stroke-width', 2);
    lbl(gs, CX, simY + 1, `cos_sim = f̂_imgᵀ · f̂_txt ∈ [-1, 1]`, { size: 9, weight: '600', color: COLORS.sim.stroke, font: 'monospace' });
    steps.push(makeStep(cStepId, 'Sim', 'Cosine Similarity', `sim = f̂_img · f̂_txt`, 'Dot product of normalized features = cosine similarity.', 'step-sim', COLORS.sim.stroke, COLORS.sim.fill));
    cStepId++; y = simY + simH / 2 + ROW_GAP;
  }

  // ── C3: Temperature & Contrastive Loss ──
  {
    const gs = startGroup(g, 'step-loss', cStepId);
    const h = branchHeader(gs, CX, y, cStepId, 'Contrastive Loss', `L = -log(exp(sim/τ) / Σexp)`, COLORS.loss.fill, COLORS.loss.stroke, 600);
    arrowV(gs, CX, y, h, COLORS.loss.stroke);
    const rowY = h + BOX_TO_ROW + 24;
    const tauW = 140; const tauH = 34;
    gs.append('rect').attr('x', CX - 160 - tauW / 2).attr('y', rowY - tauH / 2).attr('width', tauW).attr('height', tauH).attr('rx', 6).attr('fill', '#fff').attr('stroke', COLORS.loss.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX - 160, rowY + 1, `τ = learnable`, { size: 8.5, weight: '600', color: COLORS.loss.stroke });
    lbl(gs, CX - 160, rowY + 16, 'temperature', { size: 7, color: COLORS.muted });
    const logitW = 200;
    gs.append('rect').attr('x', CX + 80 - logitW / 2).attr('y', rowY - tauH / 2).attr('width', logitW).attr('height', tauH).attr('rx', 6).attr('fill', COLORS.loss.fill).attr('stroke', COLORS.loss.stroke).attr('stroke-width', 1);
    lbl(gs, CX + 80, rowY + 1, `logits = sim / τ`, { size: 8.5, weight: '600', color: COLORS.loss.stroke, font: 'monospace' });
    drawArrow(gs as Sel, CX - 160 + tauW / 2 + 4, rowY, CX + 80 - logitW / 2 - 4, rowY, { color: COLORS.loss.stroke });

    const lossY = rowY + tauH / 2 + ROW_GAP + 24;
    const lossW = 460; const lossH = 56;
    gs.append('rect').attr('x', CX - lossW / 2).attr('y', lossY - lossH / 2).attr('width', lossW).attr('height', lossH).attr('rx', 8).attr('fill', COLORS.loss.fill).attr('stroke', COLORS.loss.stroke).attr('stroke-width', 1.5);
    arrowV(gs, CX + 80, rowY + tauH / 2, lossY - lossH / 2, COLORS.loss.stroke);
    lbl(gs, CX, lossY - 8, 'InfoNCE Loss (symmetric cross-entropy)', { size: 9, weight: '700', color: COLORS.loss.stroke });
    lbl(gs, CX, lossY + 8, `L = ½(L_i2t + L_t2i)   over batch of N pairs`, { size: 8, color: COLORS.loss.stroke, font: 'monospace' });
    lbl(gs, CX, lossY + 22, `pull matching pairs, push mismatched`, { size: 7.5, color: COLORS.muted });

    steps.push(makeStep(cStepId, 'Loss', 'Contrastive Loss', `InfoNCE`, 'Symmetric cross-entropy over image-text similarity.', 'step-loss', COLORS.loss.stroke, COLORS.loss.fill));
    y = lossY + lossH / 2 + STEP_GAP;
  }

  // ── C4: Output ──
  {
    const gs = startGroup(g, 'step-out', cStepId);
    const outW = 500; const outH = 40;
    gs.append('rect').attr('x', CX - outW / 2).attr('y', y).attr('width', outW).attr('height', outH).attr('rx', 6).attr('fill', COLORS.out.fill).attr('stroke', COLORS.out.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX, y + outH / 2 + 1, `Aligned image-text embeddings · d_proj = ${dProj}`, { size: 9.5, weight: '600', color: COLORS.out.stroke });
    steps.push(makeStep(cStepId, 'Output', 'Aligned Embeddings', `d_proj=${dProj}`, 'Learned aligned image-text embedding space.', 'step-out', COLORS.out.stroke, COLORS.out.fill));
    y += outH + 40;
  }

  return { steps, y };
}

export function renderClipEncoderDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const nPatches = Number(params.n_patches) || 196;
  const seqLen = Number(params.seq_len) || 77;

  const root = g as unknown as Gsel;
  let y = 28;

  lbl(root, CX, y, 'CLIP Encoder', { size: 18, weight: '700', color: COLORS.textCol });
  y += 24;
  const gridN = Math.round(Math.sqrt(nPatches));
  lbl(root, CX, y, `Contrastive Language-Image Pre-training · d_model=${dModel} · ${gridN}×${gridN} patches · seq_len=${seqLen}`, { size: 10, color: COLORS.muted });
  y += 32;

  const patchDim = 16 * 16 * 3;
  const vitParams = patchDim * dModel + dModel * dModel * 4 + dModel * 4;
  const textParams = dModel * dModel * 4 + dModel * 4 + seqLen * dModel;
  const projParams = dModel * dModel * 2;
  y = drawParamSummary(root, CX, y, [`d_model=${dModel}`, `ViT≈${fmtNum(vitParams)}`, `Text≈${fmtNum(textParams)}`, `proj=${fmtNum(projParams)}`]);
  y += 20;

  const result = renderClipPipeline(root, y, dModel, nPatches, seqLen);

  let footerY = result.y + 24;

  const insightText = `CLIP trains dual encoders: a ViT processes ${gridN}×${gridN} patches (patch_size=16) into image features, while a transformer encodes ${seqLen}-token text. Both are projected to a shared d=${dModel} space, L2-normalized, and aligned via contrastive loss (InfoNCE with learned temperature τ). Matched image-text pairs are pulled together, mismatches pushed apart.`;
  const perfText = `ViT encoder: ~${fmtNum(vitParams)} params (patch embed + ${gridN}²×${dModel} attention/FFN). Text encoder: ~${fmtNum(textParams)} params. Projection heads: ${fmtNum(projParams)}. Total: ~${fmtNum(vitParams + textParams + projParams)} params.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 14;

  const codeLines = [
    '# CLIP Contrastive Learning',
    `img_features = vit_encoder(patchify(image))     # [B, ${dModel}]`,
    `txt_features = text_encoder(tokenize(text))      # [B, ${dModel}]`,
    `img_proj = img_features @ W_i                    # [B, ${dModel}]`,
    `txt_proj = txt_features @ W_t                    # [B, ${dModel}]`,
    'img_norm = F.normalize(img_proj, dim=-1)',
    'txt_norm = F.normalize(txt_proj, dim=-1)',
    'similarity = img_norm @ txt_norm.T               # [B, B]',
    `logits = similarity * exp(log_temp)               # τ learnable`,
    'loss = (CE(logits, labels) + CE(logits.T, labels)) / 2',
  ];

  footerY = drawCodeAnnotation(g, 80, footerY, W - 160, 'CLIP Encoder — Contrastive Image-Text', [], codeLines);

  return { width: W, height: footerY + 24, steps: result.steps };
}
